import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"History","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Search History","slug":"_1-search-history","link":"#_1-search-history","children":[]},{"level":2,"title":"2. Keyword History","slug":"_2-keyword-history","link":"#_2-keyword-history","children":[]}],"relativePath":"user-guide/settings/history.md","filePath":"user-guide/settings/history.md","lastUpdated":1789222057000}`),a={name:`user-guide/settings/history.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to “History”">​</a></h1><p>The History settings page manages usage traces and adaptive recall rankings. Top tabs include: <strong>Search History</strong> and <strong>Keyword History</strong>.</p><h2 id="_1-search-history" tabindex="-1">1. Search History <a class="header-anchor" href="#_1-search-history" aria-label="Permalink to “1. Search History”">​</a></h2><p>Search History tracks items and applications you have actually launched, binding the search query to the target physical path:</p><ul><li><strong>Adaptive Prioritized Recall</strong>: When you type characters related to past queries, Lertaro prioritizes previously opened items at the top of results. For instance, if you launched <code>BCompare.exe</code> by searching <code>bcomp</code>, future searches for <code>bc</code> will still boost it to the top.</li><li><strong>Usage-Aware Ordering</strong>: Within history matches, Lertaro sorts by match start position, usage count, most recent opening time, and fuzzy match weight, in that order. This affects only history candidates; other result categories keep their existing ordering.</li><li><strong>Inline Window Grouping</strong>: Inside file dialogs, matching historical items within the active folder appear under &quot;Current Folder&quot;, while others appear under &quot;Global Search&quot;.</li><li><strong>Dead Link Filtering</strong>: If an indexed path is moved or deleted, Lertaro automatically skips missing entries, guaranteeing unique rows.</li><li><strong>Management Controls</strong>: <ul><li><strong>Enable History</strong>: Master toggle; existing entries are retained when disabled. New entries are not added, but reopening an existing entry still increments its usage count.</li><li><strong>Search Filter</strong>: Narrows the visible history list by keyword.</li><li><strong>Usage Counts &amp; Cleanup</strong>: Each row shows how many times it has been opened. Choose a threshold and click <strong>Clear with at most N uses</strong> to remove low-use entries, or remove individual rows and click <strong>Clear All History</strong> to wipe everything.</li><li><strong>Live Updates</strong>: The list refreshes its usage counts when another search window records a new launch.</li></ul></li></ul><h2 id="_2-keyword-history" tabindex="-1">2. Keyword History <a class="header-anchor" href="#_2-keyword-history" aria-label="Permalink to “2. Keyword History”">​</a></h2><p>Keyword History remembers the <strong>raw query strings</strong> that were actually used to execute a result or action, or to open the Full Window. Merely typing a query and dismissing or leaving the Quick Window does not add it:</p><ul><li><strong>Hotkey Navigation</strong>: Inside the Quick Window, press <strong><code>Alt+Up</code></strong> / <strong><code>Alt+Down</code></strong> to cycle backward and forward through recent queries. Press <strong><code>Ctrl+Delete</code></strong> to delete the currently active term.</li><li><strong>Usage Counts &amp; Cleanup</strong>: Each keyword shows how many times it has been used. Choose a threshold and click <strong>Clear with at most N uses</strong> to remove low-use keywords.</li><li><strong>Independent Maintenance</strong>: Includes its own <strong>Enable History</strong> toggle, search filter, single-entry deletion, and <strong>Clear All History</strong> button. When disabled, existing keywords still accumulate usage counts, while new keywords are not added.</li></ul>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};